class Solution {
	void backTrace(String currentStr, int leftNum, int rightNum, int n, ArrayList<String> list) {
		if (2 * n == currentStr.length()) {
			list.add(currentStr);
			return;
		}
		if (leftNum < n) {
			backTrace(currentStr + "(",leftNum + 1,rightNum,n,list);
		}
		if (rightNum < leftNum) {
			backTrace(currentStr + ")",leftNum,rightNum + 1,n,list);
		}
	}
	ArrayList<String> generateParenthesis(int n) {
		if (n == 0) {
			return new ArrayList<String>();
		}
		ArrayList<String> list = new ArrayList<String>();
		backTrace("",0,0,n,list);
		return list;
	}
}

class Solution {
	void dfs(ArrayList<String> list, StringBuilder sub, int size, int index, int l_count, int r_count) {
		if (l_count < 0 || r_count < 0) {
			return;
		}
		if (index == size) {
			list.add(sub.toString());
			return;
		}
		if (l_count <= r_count) {
			sub.append(')');
			dfs(list,sub,size,index + 1,l_count,r_count - 1);
			sub.deleteCharAt(index);
			sub.append('(');
			dfs(list,sub,size,index + 1,l_count - 1,r_count);
			sub.deleteCharAt(index);
		} 
		else {
			sub.append(')');
			dfs(list,sub,size,index + 1,l_count,r_count - 1);
			sub.deleteCharAt(index);
		}
	}
	ArrayList<String> generateParenthesis(int n) {
		ArrayList<String> list = new ArrayList<>();
		StringBuilder sub = new StringBuilder();
		dfs(list,sub,2 * n,0,n,n);
		return list;
	}
}

class Solution {
	int left, right, n1;
	StringBuilder path;
	ArrayList<String> ret;
	void dfs() {
		if (right == n1) {
			ret.add(path.toString());
			return;
		}
		if (left < n1) {
			path.append('(');
			left++;
			dfs();
			path.deleteCharAt(path.length() - 1);
			left--;
		}
		if (right < left) {
			path.append(')');
			right++;
			dfs();
			path.deleteCharAt(path.length() - 1);
			right--;
		}
	}
	ArrayList<String> generateParenthesis(int n) {
		ret = new ArrayList<>();
		path = new StringBuilder();
		n1 = n;
		left = right = 0;
		dfs();
		return ret;
	}
}

