	ListNode findKthNodeFromEnd(ListNode head, int k) {
		if (k == 0 || head == null) {
			return head;
		}
		if (head.next == null && k == 1) {
			return head;
		}
		if (head.next == null && k > 1) {
			return null;
		}
		ListNode slow = head;
		ListNode fast = head;
		int count = 1;
		while (count < k && fast.next != null) {
			fast = fast.next;
			count++;
		}
		if (count < k) {
			return null;
		}
		while (fast.next != null) {
			slow = slow.next;
			fast = fast.next;
		}
		return slow;
	}
}

