		ArrayList<Integer> res = new ArrayList<Integer>();
		int left = 0, right = array.length - 1;
		while (left < right) {
			if (array[left] + array[right] == sum) {
				res.add(array[left]);
				res.add(array[right]);
				break;
			} 
			else if (array[left] + array[right] > sum) {
				right--;
			} 
			else {
				left++;
			}
		}
		return res;
	}
}

