class Solution {
	ArrayList<Integer> FindNumbersWithSum(int[] array, int sum) {
		ArrayList<Integer> list = new ArrayList<>();
		for (int i = 0; i < array.length - 1; i++) {
			int n = sum - array[i];
			int left = i + 1;
			int right = array.length - 1;
			while (left <= right) {
				int mid = left + right >> 1;
				if (array[mid] < n) {
					left = mid + 1;
				} 
				else if (array[mid] > n) {
					right = mid - 1;
				} 
				else {
					list.add(array[i]);
					list.add(array[mid]);
					return list;
				}
			}
		}
		return list;
	}
}

