class Solution {
	int[][] rotateMatrix(int[][] mat, int n) {
		for (int i = 0; i < n; i++) {
			for (int j = i + 1; j < n; j++) {
				swap(mat,i,j,j,i);
			}
		}
		int c = n / 2;
		int j = 0;
		while (c > 0) {
			for (int i = 0; i < n; i++) {
				swap(mat,i,j,i,n - 1);
			}
			j++;
			c--;
		}
		return mat;
	}
	void swap(int[][] mat, int i, int j, int m, int n) {
		mat[i][j] = mat[i][j] ^ mat[m][n];
		mat[m][n] = mat[i][j] ^ mat[m][n];
		mat[i][j] = mat[i][j] ^ mat[m][n];
	}
