class Solution {
	int[][] rotateMatrix(int[][] mat, int n) {
		int[][] res = new int[n][n];
		int index = n;
		for (int i = 0; i < mat.length; i++) {
			int[] ch = mat[i];
			res[i] = new int[n];
			for (int j = 0; j < ch.length; j++) {
				res[i][j] = mat[index - 1][i];
				index--;
			}
			index = n;
		}
		return res;
	}
}

class Solution {
	void rotateEdge(int[][] m, int x1, int y1, int x2, int y2) {
		int temp = 0;
		for (int i = 0; i < x2 - x1; i++) {
			temp = m[x1][y1 + i];
			m[x1][y1 + i] = m[x2 - i][y1];
			m[x2 - i][y1] = m[x2][y2 - i];
			m[x2][y2 - i] = m[x1 + i][y2];
			m[x1 + i][y2] = temp;
		}
	}
	int[][] rotateMatrix(int[][] mat, int n) {
		int x1 = 0, y1 = 0;
		int x2 = mat.length - 1, y2 = mat[0].length - 1;
		while (x1 <= x2 && y1 <= y2) {
			rotateEdge(mat,x1++,y1++,x2--,y2--);
		}
		return mat;
	}
}

