		ListNode tail = head;
		while (tail.next != null) {
			tail = tail.next;
			length++;
		}
		tail.next = head;
		k = k % length;
		ListNode newTail = head;
		for (int i = 0; i < length - k; i++) {
			newTail = newTail.next;
