class Solution {
	Map<Integer, Integer> inMap = new HashMap<>();
	TreeNode buildTree(int[] preOrder, int[] vinOrder, int preStart, int preEnd, int inLeft, int inEnd) {
		if (preEnd < preStart) {
			return null;
		}
		int current = preOrder[preStart];
		TreeNode root = new TreeNode(current);
		int currentIndex = inMap.get(current);
		int leftLeng = currentIndex - inLeft;
		root.left = buildTree(preOrder,vinOrder,preStart + 1,preStart + leftLeng,inLeft,currentIndex - 1);
		root.right = buildTree(preOrder,vinOrder,preStart + leftLeng,preEnd,currentIndex + 1,inEnd);
		return root;
	}
	TreeNode reConstructBinaryTree(int[] preOrder, int[] vinOrder) {
		for (int i = 0; i < vinOrder.length; i++) {
			inMap.put(vinOrder[i],i);
		}
		return buildTree(preOrder,vinOrder,0,preOrder.length - 1,0,vinOrder.length - 1);
	}
}

class Solution {
	TreeNode reConstructBinaryTree(int[] preOrder, int[] vinOrder) {
		if (preOrder == null || preOrder.length == 0) {
			return null;
		}
		TreeNode root = new TreeNode(preOrder[0]);
		int[] leftMid = null;
		int[] rightMid = null;
		int index = 0;
		for (int i = 0; i < vinOrder.length; i++) {
			if (root.val == vinOrder[i]) {
				leftMid = new int[i];
				index = i;
			}
			if (i == vinOrder.length - 1) {
				rightMid = new int[vinOrder.length - leftMid.length];
			}
		}
		leftMid = Arrays.copyOfRange(vinOrder,0,index);
		rightMid = Arrays.copyOfRange(vinOrder,index + 1,preOrder.length);
		int[] preleft = Arrays.copyOfRange(preOrder,1,leftMid.length + 1);
		int[] preRight = Arrays.copyOfRange(preOrder,leftMid.length + 1,preOrder.length);
		root.left = reConstructBinaryTree(preleft,leftMid);
		root.right = reConstructBinaryTree(preRight,rightMid);
		return root;
	}
}

class Solution {
	TreeNode reConstructBinaryTree(int[] pre, int[] in) {
		return rebuild(pre,0,pre.length - 1,in,0,in.length - 1);
	}
	TreeNode rebuild(int[] pre, int preLeft, int preRight, int[] in, int inLeft, int inRight) {
		if (preLeft > preRight) {
			return null;
		}
		TreeNode root = new TreeNode(pre[preLeft]);
		int rootIndex = inLeft;
		while (rootIndex <= inRight && in[rootIndex] != pre[preLeft]) {
			rootIndex++;
		}
		root.left = rebuild(pre,preLeft + 1,preLeft + rootIndex - inLeft,in,inLeft,rootIndex - 1);
		root.right = rebuild(pre,preLeft + rootIndex - inLeft + 1,preRight,in,rootIndex + 1,inRight);
		return root;
	}
}

class Solution {
