class Solution {
	TreeNode build(int[] preOrder, int[] inOrder, int preStart, int inStart, int inEnd) {
		if (inEnd < inStart) {
			return null;
		}
		int rootVal = preOrder[preStart];
		TreeNode root = new TreeNode(rootVal);
		int index = 0;
		for (int i = inStart; i <= inEnd; i++) {
			if (inOrder[i] == rootVal) {
				index = i;
				break;
			}
		}
		int len = index - inStart;
		root.left = build(preOrder,inOrder,preStart + 1,inStart,index - 1);
		root.right = build(preOrder,inOrder,preStart + len,index + 1,inEnd);
		return root;
	}
	TreeNode reConstructBinaryTree(int[] preOrder, int[] vinOrder) {
		return build(preOrder,vinOrder,0,0,vinOrder.length - 1);
	}
}

class Solution {
	TreeNode reConstructBinaryTree(int[] pre, int[] vin) {
		if (pre.length == 0 || vin.length == 0) {
			return null;
		}
		TreeNode root = new TreeNode(pre[0]);
		int rootIndex = 0;
		for (int i = 0; i < vin.length; i++) {
			if (root.val == vin[i]) {
				rootIndex = i;
				break;
			}
		}
		root.left = reConstructBinaryTree(Arrays.copyOfRange(pre,1,rootIndex + 1),Arrays.copyOfRange(vin,0,rootIndex));
		root.right = reConstructBinaryTree(Arrays.copyOfRange(pre,rootIndex + 1,pre.length),Arrays.copyOfRange(vin,rootIndex + 1,vin.length));
		return root;
	}
}

