class Solution {
	TreeNode getTreeNode(int preStart, int inStart, int inEnd, int[] pre, int[] vin) {
		if (preStart > pre.length - 1 || inStart > inEnd) {
			return null;
		}
		TreeNode tree = new TreeNode(pre[preStart]);
		int index = 0;
		for (int i = inStart; i <= inEnd; i++) {
			if (vin[i] == tree.val) {
				index = i;
				break;
			}
		}
		tree.left = getTreeNode(preStart + 1,inStart,index - 1,pre,vin);
		tree.right = getTreeNode(preStart + index - inStart + 1,index + 1,inEnd,pre,vin);
		return tree;
	}
	TreeNode reConstructBinaryTree(int[] pre, int[] vin) {
		return getTreeNode(0,0,vin.length - 1,pre,vin);
	}
}

class Solution {
	TreeNode build(int[] pre, int l, int r, int[] in, int x, int y) {
		if (l > r) {
			return null;
		}
		int t = pre[l];
		int p = -1;
		for (int i = x; i <= y; i++) {
			if (t == in[i]) {
				p = i;
			}
		}
		TreeNode node = new TreeNode(t);
		node.left = build(pre,l + 1,l + (p - x),in,x,p - 1);
		node.right = build(pre,l + (p - x),r,in,p + 1,y);
		return node;
	}
	TreeNode reConstructBinaryTree(int[] pre, int[] in) {
		return build(pre,0,pre.length - 1,in,0,in.length - 1);
	}
}

