		Stack<ListNode> stack = new Stack<>();
		int length = n - m;
		while (m > 1) {
			m--;
			pre = pre.next;
		}
		head = pre.next;
		for (int i = 0; i <= length; i++) {
			stack.push(head);
			head = head.next;
		}
