			return head;
		}
		ListNode fakeHead = new ListNode(-1);
		fakeHead.next = head;
		ListNode pre = fakeHead;
		ListNode tmp = null;
		for (int i = 1; i < m; i++) {
			pre = pre.next;
		}
		ListNode p1 = pre.next;
