		while (M-- != 1) {
			s1.push(cur);
			cur = cur.next;
		}
		int count = n - m + 1;
		while (count-- != 0) {
			s2.push(cur);
			cur = cur.next;
		}
		ListNode newHead = new ListNode(-1);
		ListNode tmp1 = newHead;
