		this.res = Math.max(this.res,c.val);
		if (c.left == null && c.right == null) {
			return c.val;
		}
		int l = 0;
		int r = 0;
		if (c.left != null) {
			l = partMax(c.left);
		}
		if (c.right != null) {
			r = partMax(c.right);
		}
		int mlr = Math.max(l,r);
		int tr = Math.max(0,Math.max(c.val,c.val + mlr));
