class Solution {
	int lengthOfLongestSubstring(String s) {
		HashMap<Character, Integer> charSet = new HashMap<>();
		int result = 0;
		for (int left = 0, right = 0; right < s.length(); right++) {
			if (charSet.containsKey(s.charAt(right))) {
				charSet.put(s.charAt(right),charSet.get(s.charAt(right)) + 1);
			} 
			else {
				charSet.put(s.charAt(right),1);
			}
			while (charSet.get(s.charAt(right)) > 1) {
				charSet.put(s.charAt(left),charSet.get(s.charAt(left++)) - 1);
			}
			result = Math.max(result,right - left + 1);
		}
		return result;
	}
}

class Solution {
	int lengthOfLongestSubstring(String s) {
		Map<Character, Integer> charIdx = new HashMap<>();
		int dp = 0;
		int maxLen = 0;
		for (int i = 0; i < s.length(); i++) {
			char c = s.charAt(i);
			int lastIdx_c = charIdx.getOrDefault(c,-1);
			if (lastIdx_c < i - dp) {
				dp++;
			} 
			else {
				dp = i - lastIdx_c;
			}
			maxLen = Math.max(maxLen,dp);
			charIdx.put(c,i);
		}
		return maxLen;
	}
}

class Solution {
	int lengthOfLongestSubstring(String s) {
		HashMap<Character, Integer> mp = new HashMap<>();
		int res = 0;
		int[] dp = new int[s.length() + 1];
		for (int i = 1; i <= s.length(); i++) {
			dp[i] = 1;
			if (!mp.containsKey(s.charAt(i - 1))) {
				dp[i] = dp[i - 1] + 1;
			} 
			else {
				dp[i] = Math.min(dp[i - 1] + 1,i - mp.get(s.charAt(i - 1)));
			}
			mp.put(s.charAt(i - 1),i);
			res = Math.max(res,dp[i]);
		}
		return res;
	}
}

