class Solution {
	int findKth(int[] a, int n, int K) {
		PriorityQueue<Integer> queue = new PriorityQueue<>();
		for (int i = 0; i < n; i++) {
			if (i < K) {
				queue.offer(a[i]);
			} 
			else {
				if (queue.peek() < a[i]) {
					queue.offer(a[i]);
					queue.poll();
				}
			}
		}
		return queue.peek();
	}
}

