class Solution {
	int findKth(int[] nums, int n, int k) {
		PriorityQueue<Integer> minHeap = new PriorityQueue<>();
		for (int i = 0; i < nums.length; i++) {
			if (i < k) {
				minHeap.offer(nums[i]);
				continue;
			}
			int top = minHeap.peek();
			if (nums[i] > top) {
				minHeap.poll();
				minHeap.offer(nums[i]);
			}
		}
		return minHeap.peek();
	}
}

