		for (int x: a) {	
			if (queue.size() < K) {
				queue.add(x);
			} 
			else {
				if (x > queue.peek()) {
					queue.poll();
					queue.add(x);
				}
			}
		}
		return queue.isEmpty() ? 0 : queue.peek();
	}
}

