	int findKth(int[] a, int n, int K) {
		PriorityQueue<Integer> heap = new PriorityQueue<>(new Comparator<Integer>());
		for (int i = 0; i < n; i++) {
			heap.offer(a[i]);
		}
		for (int i = 0; i < K - 1; i++) {
			heap.poll();
		}
		return heap.poll();
	}
}

class Solution {
	int cnt = 0;
	int InversePairs(int[] array) {
		if (array.length <= 1) {
			return 0;
		}
		int len = 1;
		while (len < array.length) {
			int start = 0;
			while (start + 2 * len - 1 < array.length) {
				int mid = start + len - 1;
				int end = start + 2 * len - 1;
				merge(array,start,mid,end);
				start = start + 2 * len;
			}
			if (start + len - 1 < array.length) {
				merge(array,start,start + len - 1,array.length - 1);
			}
			len = len * 2;
		}
		return cnt;
	}
	void merge(int[] arr, int start, int mid, int end) {
		int i = start;
		int j = mid + 1;
		int[] temp = new int[end - start + 1];
		int index = 0;
		while (i <= mid && j <= end) {
			if (arr[i] <= arr[j]) {
				temp[index++] = arr[i++];
			} 
			else {
				temp[index++] = arr[j++];
				cnt = (cnt + (mid - i + 1)) % 1000000007;
			}
		}
		while (i <= mid) {
			temp[index++] = arr[i++];
		}
		while (j <= end) {
			temp[index++] = arr[j++];
		}
		for (int k = start; k <= end; k++) {
			arr[k] = temp[k - start];
		}
	}
}

class Solution {
	int InversePairs(int[] array) {
		if (array == null || array.length == 0) {
			return 0;
		}
		int[] copy = new int[array.length];
		for (int i = 0; i < array.length; i++) {
			copy[i] = array[i];
		}
		int count = InversePairsCore(array,copy,0,array.length - 1);
		return count;
	}
	int InversePairsCore(int[] array, int[] copy, int low, int high) {
		if (low == high) {
			return 0;
		}
		int mid = (low + high) >> 1;
		int leftCount = InversePairsCore(array,copy,low,mid) % 1000000007;
		int rightCount = InversePairsCore(array,copy,mid + 1,high) % 1000000007;
		int count = 0;
		int i = mid, j = high, locCopy = high;
		while (i >= low && j > mid) {
			if (array[i] > array[j]) {
				count += j - mid;
				copy[locCopy--] = array[i--];
				if (count >= 1000000007) {
					count %= 1000000007;
				}
			} 
			else {
				copy[locCopy--] = array[j--];
			}
		}
		for (; i >= low; i--) {
			copy[locCopy--] = array[i];
		}
		for (; j > mid; j--) {
			copy[locCopy--] = array[j];
		}
		for (int s = low; s <= high; s++) {
			array[s] = copy[s];
		}
		return (leftCount + rightCount) % 1000000007;
	}
}

