class Solution {
	boolean isValid(int x, int y, int k) {
		int sum = 0;
		while (x != 0 && y != 0) {
			sum += x % 10 + y % 10;
			x /= 10;
			y /= 10;
		}
		while (x != 0) {
			sum += x % 10;
			x /= 10;
		}
		while (y != 0) {
			sum += y % 10;
			y /= 10;
		}
		return sum <= k ? true : false;
	}
	int movingCount(int threshold, int rows, int cols) {
