			return 1;
		}
		int[][] sign = new int[rows][cols];
		return process(0,0,rows,cols,threshold,sign);
	}
	int process(int x, int y, int m, int n, int k, int[][] sign) {
		if (x < 0 || x >= m || y < 0 || y >= n || sign[x][y] == 1 || !isValid(x,y,k)) {
