class Solution {
	int last = -1;
	boolean isLevel(TreeNode root) {
		if (root == null) {
			return true;
		}
		LinkedList<TreeNode> queue = new LinkedList<>();
		queue.offer(root);
		while (!queue.isEmpty()) {
			int size = queue.size();
			int m = 0;
			for (int i = 0; i < size; i++) {
				TreeNode node = queue.poll();
				if (node == null) {
					m++;
				}
				if (m == size) {
					return true;
				}
				if (node == null && queue.peek() != null) {
					return false;
				}
				if (node != null) {
					queue.offer(node.left);
					queue.offer(node.right);
				} 
				else {
					queue.offer(null);
					queue.offer(null);
				}
			}
		}
		return true;
	}
	boolean isSearchTree(TreeNode root) {
		if (root == null) {
			return true;
		}
		boolean left = isSearchTree(root.left);
		if (last >= root.val) {
			return false;
		}
		last = root.val;
		boolean right = isSearchTree(root.right);
		return left && right;
	}
	boolean[] judgeIt(TreeNode root) {
		boolean[] ret = new boolean[2];
		boolean search = isSearchTree(root);
		boolean level = isLevel(root);
		ret[0] = search;
		ret[1] = level;
		return ret;
	}
}

