class Solution {
	int[] postorderTraversal(TreeNode root) {
		List<Integer> result = new ArrayList<>();
		Stack<TreeNode> stack = new Stack<>();
		stack.add(root);
		while (!stack.isEmpty()) {
			TreeNode pop = stack.pop();
			if (pop != null) {
				result.add(pop.val);
				stack.add(pop.left);
				stack.add(pop.right);
			}
		}
		int[] r = new int[result.size()];
		int k = result.size() - 1;
		for (int i = result.size() - 1; i >= 0; i--) {
			r[k - i] = result.get(i);
		}
		return r;
	}
}

class Solution {
