class Solution {
	int[] postorderTraversal(TreeNode root) {
		List<Integer> res = new ArrayList<>();
		Stack<TreeNode> s = new Stack<>();
		if (root != null) {
			s.add(root);
		}
		while (!s.isEmpty()) {
			TreeNode x = s.pop();
			res.add(x.val);
			if (x.left != null) {
				s.push(x.left);
			}
			if (x.right != null) {
				s.push(x.right);
			}
		}
		int n = res.size();
		int[] ans = new int[n];
		for (int i = n - 1; i >= 0; i--) {
			ans[n - 1 - i] = res.get(i);
		}
		return ans;
	}
}

