	ListNode buildLinkedListByStack(Stack<ListNode> stack) {
		if (stack == null || stack.empty()) {
			return null;
		}
		ListNode head = stack.pop();
		ListNode currentNode = head;
		ListNode nextNode;
		while (!stack.empty()) {
