		int l = 0, r = nums.length - 1;
		while (l < r) {
			int mid = l + ((r - l) >> 1);
			if (nums[mid] > nums[mid + 1]) {
				r = mid;
			} 
			else {
				l = mid + 1;
			}
		}
		return l;
	}
}

