class Solution {
	int findPeakElement(int[] nums) {
		if (nums == null) {
			return -1;
		}
		if (nums.length == 1) {
			return 0;
		}
		if (nums.length == 2) {
			return nums[0] > nums[1] ? 0 : 1;
		}
		int left = 0;
		int right = nums.length - 1;
		int mid = 0;
		while (left < right) {
			mid = (left + right) / 2;
			if (mid == 0) {
				return mid;
			}
			if (left == mid) {
				return right;
			}
			if (nums[mid - 1] > nums[mid + 1]) {
				if (nums[mid] > nums[mid - 1]) {
					return mid;
				} 
				else {
					right = mid;
				}
			} 
			else {
				if (nums[mid] > nums[mid + 1]) {
					return mid;
				} 
				else {
					left = mid;
				}
			}
		}
		return mid;
	}
}

class Solution {
	int findPeakElement(int[] nums) {
		int length = nums.length;
		if (length == 1) {
			return 0;
		}
		if (nums[0] > nums[1]) {
			return 0;
		}
		if (nums[length - 1] > nums[length - 2]) {
			return length - 1;
		}
		int min = 1;
		int max = length - 2;
		int mid = (min + max) / 2;
		int res = peek(min,max,mid,nums);
		return res;
	}
	int peek(int min, int max, int mid, int[] nums) {
		if (min > max) {
			return -1;
		}
		if (nums[mid] > nums[mid - 1] && nums[mid] > nums[mid + 1]) {
			return mid;
		} 
		else {
			int max1 = mid - 1;
			int temp = peek(min,max1,(min + max1) / 2,nums);
			if (temp != -1) {
				return temp;
			}
			int min1 = mid + 1;
			temp = peek(min1,max,(mid + 1) / 2,nums);
			if (temp != -1) {
				return temp;
			}
		}
		return -1;
	}
}

class Solution {
	int findPeakElement(int[] nums) {
		int len = nums.length;
		if (len == 1) {
			return 0;
		}
		if (nums[0] > nums[1]) {
			return 0;
		}
		if (nums[len - 2] < nums[len - 1]) {
			return len - 1;
		}
		int right = len - 2;
		int left = 1;
		while (left <= right) {
			if (nums[left - 1] < nums[left] && nums[left] > nums[left + 1]) {
				return left;
			}
			if (nums[right - 1] < nums[right] && nums[right] > nums[right + 1]) {
				return right;
			}
			left++;
			right--;
		}
		return 0;
	}
}

class Solution {
