		if (nums[nums.length - 1] > nums[nums.length - 2]) {
			return nums.length - 1;
		}
		int L = 0;
		int R = nums.length - 1;
		int index = L + ((R - L) >> 1);
		while (L < R) {
			if (nums[index] > nums[index - 1] && nums[index] > nums[index + 1]) {
				return index;
			}
			if (nums[index] < nums[index - 1]) {
				R = index - 1;
				index = L + ((R - L) >> 1);
			}
			if (nums[index] < nums[index + 1]) {
				L = index + 1;
				index = L + ((R - L) >> 1);
			}
		}
		return index;
	}
}

