		ListNode temp = newList;
		while (head.next != null && head.val != val) {
			if (head.next.val == val) {
				temp = head;
			}
			head = head.next;
		}
		if (temp == null) {
			return newList.next;
		} 
		else {
			temp.next = head.next;
			return newList.next;
		}
	}
}

