class Solution {
	int findNthDigit(int n) {
		int digit = 1;
		long start = 1;
		long sum = 9;
		while (n > sum) {
			n -= sum;
			start *= 10;
			digit++;
			sum = 9 * start;
		}
		String num = "" + (start + (n - 1) / digit);
		int index = (n - 1) % digit;
		return (int) (num.charAt(index)) - (int) ('0');
	}
