class Solution {
	int findNthDigit(int n) {
		int digcount = 1;
		int start = 1;
		int end = 9;
		if (n <= 0) {
			return 0;
		}
		while (n > end) {
			n -= end;
			digcount++;
			start = start * 10;
			end = start * end;
		}
		String num = "" + (start + (n - 1) / digcount);
		int numIndex = (int) (n - 1) % digcount;
		return Integer.parseInt(num.charAt(numIndex) + "");
	}
}

class Solution {
	int findNthDigit(int n) {
		if (n <= 0) {
			return 0;
		}
		int x = 1;
		long start = 1;
		long count = 9;
		while (n > count) {
			n -= count;
			x++;
			start *= 10;
			count = 9 * x;
		}
		String group = (n - 1) / x + start + "";
		int i = (n - 1) % x;
		return Integer.parseInt(group.charAt(i) + "");
	}
}

