			ans[i] = res[i];
		}
		return ans;
	}
	int binarySearch(int[] arr, int left, int right, int num) {
		while (left < right) {
			int mid = left + (right - left) / 2;
			if (arr[mid] < num) {
				left = mid + 1;
			} 
			else {
				right = mid;
			}
		}
		return left;
	}
