class Solution {
	int LIS(int[] arr) {
		int n = arr.length;
		if (n == 0) {
			return 0;
		}
		int[] tail = new int[n];
		int end = -1;
		for (int i = 0; i < n; i++) {
			if (i == 0 || tail[end] < arr[i]) {
				tail[++end] = arr[i];
			} 
			else {
				int index = binarySearch(tail,end,arr[i]);
				tail[index] = arr[i];
			}
		}
		return end + 1;
	}
	int binarySearch(int[] tail, int end, int target) {
		int l = 0;
		int r = end;
		while (l < r) {
			int mid = l + (r - l) / 2;
			if (tail[mid] >= target) {
				r = mid;
			} 
			else {
				l = mid + 1;
			}
		}
		return l;
	}
}

