		int n = arr.length;
		if (n == 0) {
			return 0;
		}
		int[] dp = new int[n];
		for (int i = 0; i < n; i++) {
			dp[i] = 1;
		}
		int ret = 1;
		for (int i = 1; i < n; i++) {
			for (int j = 0; j < i; j++) {
				if (arr[j] < arr[i]) {
					dp[i] = Math.max(dp[j] + 1,dp[i]);
				}
			}
			ret = Math.max(ret,dp[i]);
		}
		return ret;
	}
}

class Solution {
	int LIS(int[] arr) {
		int n = arr.length;
		if (n < 1) {
			return 0;
		}
		int[] dp = new int[n];
		Arrays.fill(dp,1);
		int ret = 1;
		for (int i = 1; i < n; i++) {
			for (int j = 0; j < i; j++) {
				if (arr[i] > arr[j] && dp[i] < dp[j] + 1) {
					dp[i] = dp[j] + 1;
					ret = Math.max(dp[i],ret);
				}
			}
		}
		return ret;
	}
}

