class Solution {
	int result = 0;
	int[] COMPUTE_PREFIX_FUNCTION(String S) {
		int m = S.length();
		char[] charsS = S.toCharArray();
		int[] prefix = new int[m];
		prefix[0] = 0;
		int k = 0;
		for (int q = 2; q <= m; q++) {
			while (k > 0 && charsS[k] != charsS[q - 1]) {
				k = prefix[k];
			}
			if (charsS[k] == charsS[q - 1]) {
				k = k + 1;
			}
			prefix[q - 1] = k;
		}
		return prefix;
	}
	void KMP_MATCHER(String T, String S) {
		int n = T.length();
		int m = S.length();
		char[] charsT = T.toCharArray();
		char[] charsS = S.toCharArray();
		int[] prefix = COMPUTE_PREFIX_FUNCTION(S);
		int q = 0;
		for (int i = 1; i <= n; i++) {
			while (q > 0 && charsS[q] != charsT[i - 1]) {
				q = prefix[q - 1];
			}
			if (charsS[q] == charsT[i - 1]) {
				q = q + 1;
			}
			if (q == m) {
				result++;
				q = prefix[q - 1];
			}
		}
	}
	int kmp(String S, String T) {
		KMP_MATCHER(T,S);
		return result;
	}
}

class Solution {
	int kmp(String S, String T) {
		int[] next = new int[S.length()];
		int j = 0;
		for (int i = 1; i < S.length(); i++) {
			while (j > 0 && S.charAt(j) != T.charAt(i)) {
				j = next[j - 1];
			}
			if (S.charAt(j) == T.charAt(i)) {
				j++;
			}
			next[i] = j;
		}
		j = 0;
		int ans = 0;
		for (int i = 0; i < T.length(); i++) {
			while (j > 0 && S.charAt(j) != T.charAt(i)) {
				j = next[j - 1];
			}
			if (S.charAt(j) == T.charAt(i)) {
				j++;
			}
			if (j == S.length()) {
				ans++;
				j = next[j - 1];
			}
		}
		return ans;
	}
}

class Solution {
	void getNext(String s, int[] next) {
		int i = 1, j = 0;
		for (; i < s.length(); ++i) {
			if (j > 0 && s.charAt(i) != s.charAt(j)) {
				j = next[j - 1];
			}
			if (s.charAt(i) == s.charAt(j)) {
				j++;
			}
			next[i] = j;
		}
	}
	int kmp(String S, String T) {
		int count = 0;
		int[] next = new int[S.length()];
		getNext(S,next);
		for (int i = 0, j = 0; i < T.length(); ++i) {
			if (j > 0 && S.charAt(j) != T.charAt(i)) {
				j = next[j - 1];
			}
			if (S.charAt(j) == T.charAt(i)) {
				j++;
			}
			if (j == S.length()) {
				count++;
				j = next[j - 1];
			}
		}
		return count;
	}
}

