class Solution {
	int kmp(String S, String T) {
		int m = S.length(), n = T.length();
		if (m > n || n == 0) {
			return 0;
		}
		int cnt = 0;
		for (int i = 0, j = 0; i < n; i++) {
			while (j > 0 && T.charAt(i) != S.charAt(j)) {
				i = i - j + 1;
				j = 0;
			}
			if (T.charAt(i) == S.charAt(j)) {
				j++;
			}
			if (j == m) {
				cnt++;
				i = i - j + 2;
				j = 0;
			}
		}
		return cnt;
	}
}

