class Solution {
	void initNext(int[] next, char[] s) {
		for (int i = 1, j = 0; i < s.length; i++) {
			while (j > 1 && s[i] != s[j]) {
				j = next[j - 1];
			}
			if (s[i] == s[j]) {
				j++;
			}
			next[i] = j;
		}
	}
	int kmp(String S, String T) {
		char[] s = S.toCharArray();
		char[] t = T.toCharArray();
		int[] next = new int[s.length];
		int res = 0;
		initNext(next,s);
		for (int i = 0, j = 0; i < t.length; i++) {
			if (j > 0 && t[i] != s[j]) {
				j = next[j - 1];
			}
			if (t[i] == s[j]) {
				j++;
			}
			if (j == s.length) {
				res++;
				j = next[j - 1];
			}
		}
		return res;
	}
}

class Solution {
	int evalRPN(String[] tokens) {
		Stack stack = new Stack<Integer>();
		int left, right;
		for (String s: tokens) {	
			if (s.equals("+")) {
				right = (int) stack.pop();
				left = (int) stack.pop();
				stack.push(left + right);
			} 
			else if (s.equals("-")) {
				right = (int) stack.pop();
				left = (int) stack.pop();
				stack.push(left - right);
			} 
			else if (s.equals("*")) {
				right = (int) stack.pop();
				left = (int) stack.pop();
				stack.push(left * right);
			} 
			else if (s.equals("/")) {
				right = (int) stack.pop();
				left = (int) stack.pop();
				stack.push(left / right);
			} 
			else {
				stack.push(Integer.valueOf(s));
			}
		}
		return (int) stack.pop();
	}
}

class Solution {
	int evalRPN(String[] tokens) {
		LinkedList<String> stack = new LinkedList<>();
		for (String token: tokens) {	
			if (!token.equals("+") && !token.equals("-")) {
				stack.push(token);
			} 
			else {
				int val1 = Integer.parseInt(stack.pop());
				int val2 = Integer.parseInt(stack.pop());
				if (token.equals("+")) {
					stack.push(String.valueOf(val2 + val1));
				} 
				else if (token.equals("-")) {
					stack.push(String.valueOf(val2 - val1));
				} 
				else if (token.equals("*")) {
					stack.push(String.valueOf(val2 * val1));
				} 
				else {
					stack.push(String.valueOf(val2 / val1));
				}
			}
		}
		return Integer.parseInt(stack.peek());
	}
}

class Solution {
	int evalRPN(String[] tokens) {
		int n = tokens.length;
		int[] arr = new int[(n + 1) / 2];
		int index = -1;
		for (String token: tokens) {	
			if (!token.equals("+") && !token.equals("-")) {
				arr[++index] = Integer.parseInt(token);
			} 
			else {
				if (token.equals("+")) {
					index--;
					arr[index] += arr[index + 1];
				} 
				else if (token.equals("-")) {
					index--;
					arr[index] -= arr[index + 1];
				} 
				else if (token.equals("*")) {
					index--;
					arr[index] *= arr[index + 1];
				} 
				else {
					index--;
					arr[index] /= arr[index + 1];
				}
			}
		}
		return arr[0];
	}
}

