class Solution {
	int evalRPN(String[] tokens) {
		int result = 0;
		int temp1;
		int temp2;
		Stack<Integer> stack = new Stack<>();
		for (String s: tokens) {	
			if (s.equals("+")) {
				temp2 = stack.pop();
				temp1 = stack.pop();
				result = temp1 + temp2;
				stack.push(result);
			} 
			else if (s.equals("-")) {
				temp2 = stack.pop();
				temp1 = stack.pop();
				result = temp1 - temp2;
				stack.push(result);
			} 
			else if (s.equals("*")) {
				temp2 = stack.pop();
				temp1 = stack.pop();
				result = temp1 * temp2;
				stack.push(result);
			} 
			else if (s.equals("/")) {
				temp2 = stack.pop();
				temp1 = stack.pop();
				result = temp1 / temp2;
				stack.push(result);
			} 
			else {
				result = Integer.parseInt(s);
				stack.push(Integer.parseInt(s));
			}
		}
		return result;
	}
}

class Solution {
	int evalRPN(String[] tokens) {
		Deque<String> stack = new ArrayDeque<>();
		for (String str: tokens) {	
			if (str.equals("+") || str.equals("-")) {
				int b = Integer.parseInt(stack.pop());
				int a = Integer.parseInt(stack.pop());
				int c;
				if (str.equals("+")) {
					c = a + b;
				} 
				else if (str.equals("-")) {
					c = a - b;
				} 
				else if (str.equals("*")) {
					c = a * b;
				} 
				else {
					c = a / b;
				}
				stack.push(String.valueOf(c));
				continue;
			}
			stack.push(str);
		}
		return Integer.parseInt(stack.pop());
	}
}

