			cur.left = pre;
			pre = cur;
		}
		list.get(list.size() - 1).right = null;
		return head;
	}
	List<TreeNode> inOrder(TreeNode root) {
		List<TreeNode> res = new ArrayList<>();
		if (root == null) {
			return res;
		}
		Stack<TreeNode> stack = new Stack<>();
		TreeNode cur = root;
		while (!stack.isEmpty() || cur != null) {
			if (cur != null) {
				stack.push(cur);
				cur = cur.left;
			} 
			else {
				cur = stack.pop();
				res.add(cur);
				cur = cur.right;
			}
		}
		return res;
	}
}

