			while (!deque.isEmpty() && num[deque.peekLast()] < num[i]) {
				deque.pollLast();
			}
			deque.offer(i);
		}
		while (r < num.length) {
			list.add(num[deque.peekFirst()]);
			while (!deque.isEmpty() && deque.peekFirst() <= l) {
				deque.pollFirst();
			}
			while (!deque.isEmpty() && num[deque.peekLast()] < num[r]) {
				deque.pollLast();
			}
			deque.offer(r);
			r++;
			l++;
		}
		list.add(num[deque.pollFirst()]);
		return list;
	}
}

