			return res;
		}
		for (int i = 0; i < size; i++) {
			pq.add(num[i]);
		}
		int pointer_out = 0, pointer_in = size;
		while (pointer_in <= num.length) {
			res.add(pq.peek());
			if (pq.peek() == num[pointer_out++]) {
				pq.poll();
			}
			if (pointer_in < num.length) {
				pq.add(num[pointer_in]);
			}
			pointer_in++;
		}
		return res;
	}
}

