class Solution {
	ListNode FindKthToTail(ListNode pHead, int k) {
		if (k == 0) {
			return null;
		}
		ListNode first = pHead;
		ListNode second = pHead;
		for (int i = 1; i <= k; i++) {
			if (first != null) {
				first = first.next;
			} 
			else {
				return null;
			}
		}
		while (first != null) {
			first = first.next;
			second = second.next;
		}
		return second;
	}
}

