class Solution {
	boolean isValidBST(TreeNode root) {
		if (root == null) {
			return false;
		}
		Stack<TreeNode> stack = new Stack<>();
		TreeNode pre = null;
		while (root != null) {
			while (root != null || !stack.isEmpty()) {
				if (root != null) {
					stack.push(root);
					root = root.left;
				} 
				else {
					root = stack.pop();
					if (pre != null && pre.val >= root.val) {
						return false;
					}
					pre = root;
					root = root.right;
				}
			}
		}
		return true;
	}
}

