class Solution {
	ListNode FindKthToTail(ListNode pHead, int k) {
		Stack<ListNode> st = new Stack<>();
		ListNode cur = pHead;
		while (cur != null) {
			st.push(cur);
			cur = cur.next;
		}
		if (st.size() < k) {
			return null;
		}
		ListNode ans = null;
		while (k-- > 0) {
			ans = st.peek();
			st.pop();
		}
		return ans;
	}
}

