class Solution {
	int maxLength(int[] arr) {
		int left = 0;
		int res = 0;
		HashMap<Integer, Integer> map = new HashMap<>();
		for (int i = 0; i < arr.length; i++) {
			if (map.containsKey(arr[i])) {
				left = Math.max(left,map.get(arr[i]) + 1);
			}
			map.put(arr[i],i);
			res = Math.max(res,i - left + 1);
		}
		return res;
	}
}

