		int[][] record = new int[s1.length() + 1][s2.length() + 1];
		for (int i = 1; i <= s1.length(); i++) {
			for (int j = 1; j <= s2.length(); j++) {
				if (s1.charAt(i - 1) == s2.charAt(j - 1)) {
					dp[i][j] = dp[i - 1][j - 1] + 1;
					record[i][j] = 1;
				} 
				else {
					if (dp[i - 1][j] > dp[i][j - 1]) {
						dp[i][j] = dp[i - 1][j];
						record[i][j] = 2;
					} 
					else {
						dp[i][j] = dp[i][j - 1];
						record[i][j] = 3;
					}
				}
			}
