			return "-1";
		}
		Stack<Character> res = new Stack<>();
		while (row >= 0 && col >= 0) {
			if (row - 1 >= 0 && record[row][col] == 1) {
				res.push(s1.charAt(row - 1));
				row--;
				col--;
			} 
