	void pile(int[] arr, int n, int len) {
		int i = n;
		if ((n * 2 + 1 < len) && (arr[i] < arr[n * 2 + 1])) {
			i = n * 2 + 1;
		}
		if ((n * 2 + 2 < len) && (arr[i] < arr[n * 2 + 2])) {
			i = n * 2 + 2;
		}
		if (i != n) {
			arr[i] = arr[i] ^ arr[n];
			arr[n] = arr[i] ^ arr[n];
			arr[i] = arr[i] ^ arr[n];
			pile(arr,i,len);
		}
	}
}

