		int gap = size / 2;
		while (gap != 0) {
			for (int i = gap; i < size; ++i) {
				int temp = arr[i];
				int j;
				for (j = i; j >= gap; j -= gap) {
					if (arr[j - gap] > temp) {
						arr[j] = arr[j - gap];
					} 
					else {
						break;
					}
				}
				arr[j] = temp;
			}
			gap = gap / 2;
		}
		return arr;
	}
