		String string = "";
		StringBuilder stringB = new StringBuilder(str);
		char c = str.toCharArray();
		if (c == null || c.length == 0) {
			return "";
		}
		for (int i = 0; i < n; i++) {
			stringB.deleteCharAt(0);
			stringB.append(c[i]);
		}
		string = stringB.toString();
		return string;
	}
}

