class Solution {
	String LeftRotateString(String str, int n) {
		String newstr = "";
		if (str.length() == 0) {
			return str;
		}
		Queue<Character> queue = new LinkedList<>();
		char[] ch = str.toCharArray();
		for (int i = 0; i < ch.length; i++) {
			queue.add(ch[i]);
		}
		for (int i = 1; i <= n; i++) {
			char tem = queue.remove();
			queue.add(tem);
		}
		for (int i = 0; i < ch.length; i++) {
			newstr += queue.remove();
		}
		return newstr;
	}
}

class Solution {
	String LeftRotateString(String str, int n) {
		if (str.isEmpty() || str.length() == 0) {
			return "";
		}
		int m = str.length();
		n = n % m;
		char[] s = str.toCharArray();
		reverse(s,0,m - 1);
		reverse(s,0,m - n);
		reverse(s,m - n,m - 1);
		return new String(s);
	}
	void reverse(char[] s, int start, int end) {
		while (start < end) {
			swap(s,start++,end--);
		}
	}
	void swap(char[] s, int a, int b) {
		char temp = s[a];
		s[a] = s[b];
		s[b] = temp;
	}
}

