			return false;
		}
		if (visit[i][j]) {
			return false;
		}
		if (cur == s.length() - 1) {
			return true;
		}
		visit[i][j] = true;
		cur++;
		if (dfs(m,s,i - 1,j,visit,cur) || dfs(m,s,i + 1,j,visit,cur)) {
			return true;
		}
		visit[i][j] = false;
		return false;
	}
