		if (i >= matrix.length || i < 0 || j >= matrix[0].length || j < 0 || matrix[i][j] != word[index]) {
			return false;
		}
		if (index == word.length - 1) {
			return true;
		}
		char tmp = matrix[i][j];
		matrix[i][j] = '.';
		boolean res = dfs(matrix,word,i + 1,j,index + 1) || dfs(matrix,word,i - 1,j,index + 1);
		matrix[i][j] = tmp;
		return res;
	}
	boolean hasPath(char[][] matrix, String word) {
		char[] words = word.toCharArray();
		for (int i = 0; i < matrix.length; i++) {
			for (int j = 0; j < matrix[0].length; j++) {
				if (dfs(matrix,words,i,j,0)) {
					return true;
				}
			}
		}
		return false;
	}
}

class Solution {
	boolean dfs(int m, int n, boolean[][] vis, char[][] matrix, int k, String word) {
		if (m < 0 || n < 0 || m >= matrix.length || n >= matrix[0].length || vis[m][n] == true) {
			return false;
		}
		if (word.charAt(word.length() - 1) == matrix[m][n] && (k == word.length() - 1)) {
			return true;
		}
		if (word.charAt(k) == matrix[m][n]) {
			vis[m][n] = true;
			if (dfs(m + 1,n,vis,matrix,k + 1,word) || dfs(m,n + 1,vis,matrix,k + 1,word)) {
				return true;
			} 
			else {
				vis[m][n] = false;
				return false;
			}
		} 
		else {
			vis[m][n] = false;
			return false;
		}
	}
	boolean hasPath(char[][] matrix, String word) {
		for (int i = 0; i < matrix.length; i++) {
			for (int j = 0; j < matrix[0].length; j++) {
				if (matrix[i][j] == word.charAt(0)) {
					boolean vis = new boolean[matrix.length][matrix[0].length];
					if (dfs(i,j,vis,matrix,0,word) == true) {
						return true;
					}
				}
			}
		}
		return false;
	}
}

class Solution {
	boolean dfs(char[][] matrix, int x, int y, int step, String word, int vis) {
		if (step == word.length()) {
			return true;
		}
		if (x >= matrix.length || x < 0) {
			return false;
		}
		if (y >= matrix[x].length || y < 0) {
			return false;
		}
		if (vis[x][y] == 1) {
			return false;
		}
		if (matrix[x][y] == word.charAt(step)) {
			vis[x][y] = 1;
			boolean result = dfs(matrix,x + 1,y,step + 1,word,vis) || dfs(matrix,x - 1,y,step + 1,word,vis);
