}

class Solution {
	boolean hasPath(char[][] matrix, String word) {
		if (word.length() == 0) {
			return true;
		}
		for (int i = 0; i < matrix.length; i++) {
			for (int j = 0; j < matrix[0].length; j++) {
				if (helper(matrix,i,j,word)) {
					return true;
				}
			}
		}
		return false;
	}
	boolean helper(char[][] matrix, int i, int j, String word) {
		if (word.length() == 0) {
			return true;
		}
		if (i < 0 || j < 0 || i >= matrix.length || j >= matrix[0].length) {
			return false;
		}
		if (word.charAt(0) == matrix[i][j]) {
			char tmp = matrix[i][j];
			matrix[i][j] = '.';
			boolean res = helper(matrix,i - 1,j,word.substring(1,word.length())) || helper(matrix,i + 1,j,word.substring(1,word.length()));
			matrix[i][j] = tmp;
			return res;
		} 
		else {
			return false;
		}
	}
}

class Solution {
	boolean hasPath(char[][] matrix, String word) {
		if (matrix == null || word == null || word.length() == 0) {
			return false;
		}
		for (int i = 0; i < matrix.length; i++) {
			for (int j = 0; j < matrix[0].length; j++) {
				boolean[][] flags = new boolean[matrix.length][matrix[0].length];
				boolean result = judge(i,j,matrix,flags,word,0);
				if (result) {
					return true;
				}
			}
		}
		return false;
	}
	boolean judge(int i, int j, char[][] matrix, boolean[][] flags, String words, int index) {
		if (index >= words.length()) {
			return true;
		}
		if (i < 0 || j < 0 || i >= matrix.length || j >= matrix[0].length || flags[i][j]) {
			return false;
		}
		flags[i][j] = true;
		if (matrix[i][j] == words.charAt(index)) {
			if (judge(i - 1,j,matrix,flags,words,index + 1) || judge(i + 1,j,matrix,flags,words,index + 1)) {
				return true;
			} 
			else {
				flags[i][j] = false;
				return false;
			}
		} 
		else {
			flags[i][j] = false;
			return false;
		}
	}
}

class Solution {
	boolean hasPath(char[][] matrix, String word) {
		for (int i = 0; i < matrix.length; i++) {
			for (int j = 0; j < matrix[0].length; j++) {
				if (isPath(matrix,word,i,j,0)) {
					return true;
				}
			}
		}
		return false;
	}
	boolean isPath(char[][] matrix, String word, int i, int j, int index) {
		if (index == word.length()) {
			return true;
		}
		if (i < 0 || i >= matrix.length || j < 0 || j >= matrix[0].length) {
			return false;
		}
		if (matrix[i][j] == '&') {
			return false;
		}
		if (word.charAt(index) == matrix[i][j]) {
			char tmp = matrix[i][j];
			matrix[i][j] = '&';
			boolean res = isPath(matrix,word,i - 1,j,index + 1) || isPath(matrix,word,i + 1,j,index + 1);
			matrix[i][j] = tmp;
			return res;
		}
		return false;
	}
}

class Solution {
	boolean hasPath(char[][] matrix, String word) {
		char[] words = word.toCharArray();
		for (int i = 0; i < matrix.length; i++) {
			for (int j = 0; j < matrix[0].length; j++) {
				if (traversal(i,j,matrix,words,0)) {
					return true;
				}
			}
		}
		return false;
	}
	boolean traversal(int i, int j, char[][] matrix, char[] words, int index) {
		if (i >= matrix.length || i < 0 || j >= matrix[0].length || j < 0 || matrix[i][j] != words[index]) {
			return false;
		}
		if (index == words.length - 1) {
			return true;
		}
		char tmp = matrix[i][j];
		matrix[i][j] = '.';
		boolean res = traversal(i + 1,j,matrix,words,index + 1) || traversal(i - 1,j,matrix,words,index + 1);
		matrix[i][j] = tmp;
		return res;
	}
}

class Solution {
	boolean hasPath(char[][] matrix, String word) {
		if (matrix.length == 0 || word == null) {
			return false;
		}
		int row = matrix.length;
		int col = matrix[0].length;
		int[][] flag = new int[row][col];
		char[] str = word.toCharArray();
		for (int i = 0; i < row; i++) {
			for (int j = 0; j < col; j++) {
				if (search(matrix,i,j,word,flag,0)) {
					return true;
				}
			}
		}
		return false;
	}
	boolean search(char[][] matrix, int i, int j, String word, int[][] flag, int index) {
		int rows = matrix.length;
		int cols = matrix[0].length;
		if (i < 0 || j < 0 || i >= rows || j >= cols || flag[i][j] == 1 || matrix[i][j] != word.charAt(index)) {
			return false;
		}
		if (index == word.length() - 1) {
			return true;
		}
		flag[i][j] = 1;
		if (search(matrix,i + 1,j,word,flag,index + 1) || search(matrix,i - 1,j,word,flag,index + 1)) {
			return true;
		}
		flag[i][j] = 0;
		return false;
	}
}

class Solution {
	boolean hasPath(char[][] matrix, String word) {
		int len = word.length();
		int count = 0;
		int n = matrix.length;
		int m = matrix[0].length;
		Boolean isVis = new Boolean[n * m];
		for (int i = 0; i < isVis.length; i++) {
			isVis[i] = false;
		}
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < m; j++) {
				if (isFind(matrix,i,j,count,word,isVis)) {
					return true;
				}
			}
		}
		return false;
	}
	boolean isFind(char[][] matrix, int row, int col, int count, String word, Boolean isVis) {
		boolean is = false;
		count++;
		if (row < 0 || row > matrix.length - 1 || col < 0 || col > matrix[0].length - 1) {
			return false;
		}
		if (isVis[row * matrix[0].length + col]) {
			return false;
		}
		if (word.charAt(count - 1) != matrix[row][col]) {
			return false;
		}
		isVis[row * matrix[0].length + col] = true;
		if (count == word.length()) {
			return true;
		}
		is = isFind(matrix,row,col + 1,count,word,isVis) || isFind(matrix,row + 1,col,count,word,isVis);
		if (!is) {
			count--;
			isVis[row * matrix[0].length + col] = false;
		}
		return is;
	}
}

class Solution {
	String compressString(String param) {
		int len = param.length();
		if (len == 1) {
			return param;
		}
		int slow = 0;
		int fast = 0;
		fast++;
		String res = new String();
		int times = 1;
		param = param + "!";
		while (slow < len) {
			if (param.charAt(slow) == param.charAt(fast)) {
				times++;
				fast++;
			} 
			else {
				if (times != 1) {
					res = res + param.charAt(slow);
				} 
				else {
					res = res + param.charAt(slow);
				}
				times = 1;
				slow = fast;
				fast++;
			}
		}
		return res;
	}
}

class Solution {
	String compressString(String param) {
		if (param.length() == 0) {
			return "";
		}
		char[] c = param.toCharArray();
		int count = 1;
		StringBuffer sb = new StringBuffer();
		for (int i = 0; i < c.length - 1; i++) {
			if (c[i] == c[i + 1]) {
				count++;
			} 
			else {
				sb.append(c[i]);
				if (count > 1) {
					sb.append(count);
				}
				count = 1;
			}
		}
		sb.append(c[c.length - 1]);
		if (count > 1) {
			sb.append(count);
		}
		return sb.toString();
	}
}

class Solution {
	String compressString(String param) {
		if (0 == param.length() || 1 == param.length()) {
			return param;
		}
		int len = param.length();
		int p = 1;
		int account = 1;
		char chr = param.charAt(0);
		StringBuffer sb = new StringBuffer("");
		while (p < len) {
			char tmp = param.charAt(p);
			if (tmp == chr) {
				account++;
				p++;
			} 
			else {
				if (account == 1) {
					sb.append(chr);
				} 
				else {
					sb.append(chr);
					sb.append(account);
				}
				chr = tmp;
				account = 1;
				p++;
			}
		}
		if (account == 1) {
			sb.append(chr);
		} 
		else {
			sb.append(chr);
			sb.append(account);
		}
		return new String(sb);
	}
}

class Solution {
	String compressString(String param) {
		if ("".equals(param)) {
			return "";
		}
		List<Map<Character, Integer>> list = new ArrayList<>();
		char[] chars = param.toCharArray();
		Character cur = chars[0];
		String compressStr = "";
		String temp = "";
		int count = 1;
		HashMap<Character, Integer> characterIntegerHashMap;
		for (int i = 0; i < chars.length; i++) {
			if (i == (chars.length - 1)) {
				characterIntegerHashMap = new HashMap<>();
				characterIntegerHashMap.put(chars[i],count);
				list.add(characterIntegerHashMap);
				count = 1;
				break;
			}
			if ((chars[i] == chars[i + 1])) {
				count++;
			} 
			else {
				characterIntegerHashMap = new HashMap<>();
				characterIntegerHashMap.put(chars[i],count);
				list.add(characterIntegerHashMap);
				count = 1;
			}
		}
		for (int i = 0; i < list.size(); i++) {
			String curStr = "";
			Character key = 'c';
			Map<Character, Integer> characterIntegerMap = list.get(i);
			Iterator<Character> iterator = characterIntegerMap.keySet().iterator();
			while (iterator.hasNext()) {
				key = iterator.next();
			}
			Integer integer = characterIntegerMap.get(key);
			if (integer == 1) {
				curStr = key.toString();
			} 
			else {
				curStr = key.toString() + integer;
			}
			compressStr += curStr;
		}
		return compressStr;
	}
}

class Solution {
	String compressString(String param) {
		if (param == null || param.equals("")) {
			return "";
		}
		StringBuffer sb = new StringBuffer();
		int i = 0;
		int j = 1;
		while (j < param.length()) {
			if (param.charAt(i) == param.charAt(j)) {
				j++;
				continue;
			} 
			else {
				sb.append(param.charAt(i));
				if (j - i > 1) {
					sb.append(j - i);
				}
				i = j;
				j++;
			}
		}
		sb.append(param.charAt(param.length() - 1));
		if (j - i > 1) {
			sb.append(j - i);
		}
		return sb.toString();
	}
}

class Solution {
	String compressString(String param) {
		StringBuilder res = new StringBuilder();
		if (param.length() <= 1) {
			return param;
		}
		int count = 1;
		for (int i = 1; i < param.length(); ++i) {
			if (param.charAt(i) == param.charAt(i - 1)) {
				count++;
			} 
			else {
				if (count == 1) {
					res.append(param.charAt(i - 1));
				} 
				else {
					res.append(param.charAt(i - 1) + "");
					count = 1;
				}
			}
		}
		if (count == 1) {
			res.append(param.charAt(param.length() - 1));
		} 
		else {
			res.append(param.charAt(param.length() - 1) + "");
		}
		return res.toString();
	}
}

class Solution {
	boolean isCompleteTree(TreeNode root) {
		Queue<TreeNode> queue = new LinkedList<>();
		queue.offer(root);
		boolean flag = false;
		while (!queue.isEmpty()) {
			TreeNode node = queue.poll();
			if (node.right != null && node.left == null) {
				return false;
			}
			if (flag && (node.left != null || node.right != null)) {
				return false;
			}
			if (node.left == null || node.right == null) {
				flag = true;
			}
			if (node.left != null) {
				queue.offer(node.left);
			}
			if (node.right != null) {
				queue.offer(node.right);
			}
		}
		return true;
	}
}

class Solution {
