class Solution {
	boolean isCompleteTree(TreeNode root) {
		Queue<TreeNode> queue = new LinkedList<>();
		queue.add(root);
		boolean noCompleteFlag = false;
		while (!queue.isEmpty()) {
			TreeNode poll = queue.poll();
			if (poll == null) {
				noCompleteFlag = true;
				continue;
			}
			if (poll != null && noCompleteFlag) {
				return false;
			}
			queue.add(poll.left);
			queue.add(poll.right);
		}
		return true;
	}
}

