class Solution {
	boolean isCompleteTree(TreeNode root) {
		return levelOrder(root);
	}
	boolean levelOrder(TreeNode root) {
		Queue<TreeNode> q = new LinkedList<>();
		q.offer(root);
		boolean res = false;
		while (!q.isEmpty()) {
			int size = q.size();
			for (int i = 0; i < size; i++) {
				TreeNode now = q.poll();
				if (now == null) {
					res = true;
				} 
				else {
					if (res) {
						return false;
					}
					q.offer(now.left);
					q.offer(now.right);
				}
			}
		}
		return res;
	}
