class Solution {
	int[] preorderTraversal(TreeNode root) {
		LinkedList<TreeNode> stack = new LinkedList<>();
		ArrayList<Integer> list = new ArrayList<>();
		TreeNode curr = root;
		while (curr != null || !stack.isEmpty()) {
			if (curr != null) {
				list.add(curr.val);
				stack.push(curr);
				curr = curr.left;
			} 
			else {
				TreeNode pop = stack.pop();
				curr = pop.right;
			}
		}
		return list.stream().mapToInt().toArray();
	}
}

