class Solution {
	int[] preorderTraversal(TreeNode root) {
		List<Integer> result = new ArrayList<>();
		Stack<TreeNode> stack = new Stack<>();
		stack.add(root);
		while (!stack.isEmpty()) {
			TreeNode pop = stack.pop();
			if (pop != null) {
				result.add(pop.val);
				stack.add(pop.right);
				stack.add(pop.left);
			}
		}
		int[] r = new int[result.size()];
		for (int i = result.size() - 1; i >= 0; i--) {
			r[i] = result.get(i);
		}
		return r;
	}
}

