		for (int j = 0; j < i; j++) {
			treeList[j] = temp[j];
		}
		return treeList;
	}
	int recursivelyPreorder(TreeNode vroot, int[] temp, int i) {
		temp[i++] = vroot.val;
		if (vroot.left != null) {
			i = recursivelyPreorder(vroot.left,temp,i);
		}
		if (vroot.right != null) {
			i = recursivelyPreorder(vroot.right,temp,i);
		}
		return i;
	}
}

