		int length = nums.length;
		if (length == 0) {
			return 1;
		}
		Arrays.sort(nums);
		int i = 0;
		for (; i < length; i++) {
			if (nums[i] > 0) {
				break;
			}
		}
		if (i == length) {
			return 1;
		}
		int value = 1;
		int j = i;
		for (; j < length; j++) {
			if (nums[j] == value) {
				value++;
				continue;
			} 
			else {
				return value;
			}
		}
		return j == length ? value : 1;
	}
}

class Solution {
	int minNumberDisappeared(int[] nums) {
		if (nums.length == 1) {
			return 1;
		}
		Arrays.sort(nums);
		int min_v = 1;
		for (int i = 0; i < nums.length; i++) {
			if (nums[i] > 0 && nums[i] > min_v) {
				return min_v;
			}
			if (min_v == nums[i]) {
				min_v++;
			}
		}
		return min_v;
	}
}

class Solution {
	int minNumberDisappeared(int[] nums) {
		if (nums == null || nums.length == 0) {
			return 1;
		}
		int ret = 0;
		int len = nums.length;
		Arrays.sort(nums);
		int i = 0;
		while (i < len && nums[i] <= 0) {
			i++;
		}
		if (nums[i] - 1 >= 1) {
			return 1;
		}
		while (i < len - 1) {
			if (nums[i] + 1 < nums[i + 1]) {
				return nums[i] + 1;
			}
			i++;
		}
		ret = nums[len - 1] + 1;
		return ret;
	}
}

class Solution {
	int[][] foundMonotoneStack(int[] nums) {
		if (nums.length < 1) {
			return null;
		}
		int[] left = new int[nums.length];
		int[] right = new int[nums.length];
		int[][] val = new int[nums.length][2];
		left[0] = nums[0];
		right[nums.length - 1] = nums[nums.length - 1];
		for (int i = 1; i < nums.length; i++) {
			left[i] = Math.min(nums[i],left[i - 1]);
		}
		for (int j = nums.length - 2; j >= 0; j--) {
			right[j] = Math.min(nums[j],right[j + 1]);
		}
		for (int i = 0; i < nums.length; i++) {
			if (nums[i] <= right[i]) {
				val[i][1] = -1;
			} 
			else {
				int j = i + 1;
				for (; ; j++) {
					if (nums[i] > nums[j]) {
						break;
					}
				}
				val[i][1] = j;
			}
		}
		for (int i = 0; i < nums.length; i++) {
			if (nums[i] <= left[i]) {
				val[i][0] = -1;
			} 
			else {
				int j = i - 1;
				for (; ; j--) {
					if (nums[i] > nums[j]) {
						break;
					}
				}
				val[i][0] = j;
			}
		}
		return val;
	}
}

class Solution {
	int[][] foundMonotoneStack(int[] nums) {
		int n = nums.length;
		int[][] res = new int[n][2];
		Deque<Integer> stack = new ArrayDeque<>();
		for (int i = 0; i < n; i++) {
			while (!stack.isEmpty() && nums[stack.peek()] >= nums[i]) {
				stack.pop();
			}
			if (stack.isEmpty()) {
				res[i][0] = -1;
			} 
			else {
				res[i][0] = stack.peek();
			}
			stack.push(i);
		}
		stack.clear();
		for (int i = n - 1; i >= 0; i--) {
			while (!stack.isEmpty() && nums[stack.peek()] >= nums[i]) {
				stack.pop();
			}
			if (stack.isEmpty()) {
				res[i][1] = -1;
			} 
			else {
				res[i][1] = stack.peek();
			}
			stack.push(i);
		}
		return res;
	}
}

