class Solution {
	int solve(int n, int k) {
		if (k == 1) {
			return n;
		}
		if (n == 0) {
			return 0;
		}
		int h = (int) (Math.log(n) / Math.log(2)) + 1;
		if (k > h) {
			return h;
		}
		int[] dp = new int[k];
		dp[0] = 0;
		dp[1] = 1;
		int res = 1;
		while (true) {
			int dp_i_1 = 0;
			for (int i = 0; i < k; i++) {
				int temp = dp[i];
				dp[i] += dp_i_1 + 1;
				dp_i_1 = temp;
				if (dp[i] >= n) {
					return res;
				}
			}
			res++;
		}
	}
}

class Solution {
	int solve(int n, int k) {
		if (k == 1) {
			return n;
		}
		int cnt = (int) (Math.log(n) / Math.log(2)) + 1;
		if (k >= cnt) {
			return cnt;
		}
		int[] dp = new int[k + 1];
		int time = 1;
		while (true) {
			for (int i = k; i >= 1; i--) {
				dp[i] += dp[i - 1] + 1;
				if (dp[i] >= n) {
					return time;
				}
			}
			dp[1] = time++;
		}
	}
}

