class Solution {
	int dfs(int n, int k) {
		if (n == 0) {
			return 0;
		}
		if (k == 1) {
			return n;
		}
		int min = Integer.MAX_VALUE;
		for (int i = 1; i <= n; i++) {
			min = Math.min(min,Math.max(dfs(i - 1,k - 1),dfs(n - i,k)) + 1);
		}
		return min;
	}
	int solve(int n, int k) {
		return dfs(n,k);
	}
}

