class Solution {
	int search(int[] nums, int target) {
		int n = nums.length;
		if (n == 0) {
			return -1;
		}
		int l = 0, r = n - 1;
		while (l < r) {
			int mid = l + r >> 1;
			if (nums[mid] <= target) {
				l = mid;
			} 
			else {
				r = mid - 1;
			}
		}
		return nums[r] == target ? r : -1;
	}
}

class Solution {
	int search(int[] nums, int target) {
		int length = nums.length;
		if (length == 0) {
			return -1;
		}
		int start = 1;
		int end = length;
		while (start < end) {
			int index = (start + end) / 2;
			int val = nums[index - 1];
			if (val == target) {
				return index - 1;
			} 
			else if (val < target) {
				start = index + 1;
			} 
			else {
				end = index - 1;
			}
		}
		if (nums[start - 1] == target) {
			return start - 1;
		}
		return -1;
	}
}

