	}
	boolean f(int[] sequence, int start, int end) {
		if (start >= end) {
			return true;
		}
		int root = sequence[end];
		int index = 0;
		int flag = 0;
		for (int i = start; i < end; i++) {
			if (flag == 0 && sequence[i] > root) {
				flag = 1;
				index = i;
				break;
			}
