		if (flag == 1) {
			for (int i = index; i < end; i++) {
				if (sequence[i] < root) {
					return false;
				}
			}
			boolean b1 = f(sequence,start,index - 1);
			boolean b2 = f(sequence,index,end - 1);
			return b1 && b2;
		} 
		else {
			boolean b1 = f(sequence,start,end - 1);
			return b1;
		}
	}
}

