		for (int i = sequence.length - 1; i >= 0; i--) {
			if (sequence[i] > rootValue) {
				return false;
			}
			while (!stack.isEmpty() && sequence[i] < stack.peekLast()) {
				rootValue = stack.pollLast();
			}
			stack.offer(sequence[i]);
		}
		return true;
	}
}

class Solution {
	boolean VerifySquenceOfBST(int[] a) {
		if (a == null || a.length == 0) {
			return false;
		}
		return verify(a,0,a.length - 1);
	}
	boolean verify(int[] a, int s, int e) {
		if (s >= e) {
			return true;
		}
		int root = a[e];
		int p1 = s;
		while (a[p1] < root) {
			++p1;
		}
		if (p1 == e) {
			return verify(a,s,e - 1);
		} 
		else {
			for (int i = p1; i < e; ++i) {
				if (a[i] < root) {
					return false;
				}
			}
			return verify(a,s,p1 - 1) && verify(a,p1,e - 1);
		}
	}
}

