class Solution {
	int[] multiply(int[] A) {
		if (A == null || A.length == 0) {
			return null;
		}
		int[] B = new int[A.length];
		int cur = 0;
		while (cur < A.length) {
			B[cur] = 1;
			for (int i = 0; i < cur; i++) {
				B[cur] *= A[i];
			}
			for (int j = cur + 1; j < A.length; j++) {
				B[cur] *= A[j];
			}
			cur++;
		}
		return B;
	}
}

