		for (int i = 1; i < n; i++) {
			help1[i] = A[i] * help1[i - 1];
		}
		help2[n - 1] = A[n - 1];
		for (int i = n - 2; i >= 0; i--) {
			help2[i] = A[i] * help2[i + 1];
		}
		B[0] = help2[1];
		B[n - 1] = help1[n - 2];
