class Solution {
	ListNode ReverseList(ListNode head) {
		List<ListNode> arr = new ArrayList<ListNode>();
		buildArr(arr,head);
		if (arr.size() >= 1) {
			List<ListNode> reverseArr = new ArrayList<ListNode>();
			for (int i = arr.size() - 1; i >= 0; i--) {
				ListNode node = arr.get(i);
				ListNode reverseNode = new ListNode(node.val);
				reverseArr.add(reverseNode);
			}
			Iterator<ListNode> it = reverseArr.iterator();
			int count = 1;
			while (it.hasNext()) {
				ListNode node = it.next();
				if (count < reverseArr.size()) {
					node.next = reverseArr.get(count);
				}
				count++;
			}
			return reverseArr.get(0);
		}
		return null;
	}
	void buildArr(List<ListNode> arr, ListNode head) {
		if (head != null) {
			arr.add(head);
			if (head.next != null) {
				buildArr(arr,head.next);
			}
		}
	}
}

class Solution {
	ListNode ReverseList(ListNode head) {
		if (head == null) {
			return null;
		}
		Stack<ListNode> stack = new Stack<>();
		while (head != null) {
			stack.push(head);
			head = head.next;
		}
		ListNode nh = stack.peek();
		while (!stack.isEmpty()) {
			ListNode pre = stack.pop();
			if (!stack.isEmpty()) {
				pre.next = stack.peek();
			} 
			else {
				pre.next = null;
			}
		}
		return nh;
	}
}

class Solution {
	int FindGreatestSumOfSubArray(int[] array) {
		if (array.length == 1) {
			return array[0];
		}
		int maxSum = array[0];
		int sum = 0;
		for (int i = 0; i < array.length; i++) {
			sum += array[i];
			if (sum > maxSum) {
				maxSum = sum;
			}
			if (sum < 0) {
				sum = 0;
			}
		}
		return maxSum;
	}
}

