class Solution {
	ListNode FindKthToTail(ListNode head, int k) {
		if (head == null) {
			return null;
		}
		if (k == 1 && head.next == null) {
			return head;
		}
		int max = 1;
		ListNode node = head;
		ListNode nodeHead = head;
		while ((node = node.next) != null) {
			max++;
		}
		node = head;
		if (max < k) {
			return null;
		}
		for (int i = 1; i <= max - k; i++) {
			nodeHead = nodeHead.next;
			node = nodeHead;
		}
		return node;
	}
}

