class Solution {
	ArrayList<ArrayList<Integer>> resultList;
	void dfs(int[] num, ArrayList<Integer> list, int sum, int index) {
		if (list.size() >= 3 && sum != 0) {
			return;
		}
		if (index <= num.length && sum == 0 && !resultList.contains(list) && list.size() == 3) {
			resultList.add(new ArrayList<>(list));
			return;
		}
		for (int i = index; i < num.length; i++) {
			sum -= num[i];
			list.add(num[i]);
			dfs(num,list,sum,i + 1);
			sum += num[i];
			list.remove(list.size() - 1);
		}
	}
	ArrayList<ArrayList<Integer>> threeSum(int[] num) {
		resultList = new ArrayList<>();
		if (num.length == 0) {
			return resultList;
		}
		Arrays.sort(num);
		dfs(num,new ArrayList<>(),0,0);
		return resultList;
	}
}

class Solution {
	int maxlenEqualK(int[] arr, int k) {
		int maxLength = 0;
		if (arr.length == 0) {
			return 0;
		}
		for (int i = 0; i < arr.length; i++) {
			int sum = 0;
			if (arr.length - i < maxLength) {
				break;
			}
			for (int j = i; j < arr.length; j++) {
				sum += arr[j];
				if (sum == k) {
					maxLength = Math.max(j - i + 1,maxLength);
				}
			}
		}
		return maxLength;
	}
}

class Solution {
	int maxProfit(int[] prices) {
		if (prices.length == 0) {
			return 0;
		}
		int max = 0;
		int minValue = prices[0];
		for (int i = 0; i < prices.length; i++) {
			if (i != 0 && minValue > prices[0]) {
				continue;
			}
			for (int j = i; j < prices.length; j++) {
				if (prices[i] < prices[j]) {
					int count = prices[j] - prices[i];
					if (count > max) {
						max = count;
					}
				}
			}
		}
		return max;
	}
}

