class Solution {
	int sqrt(int x) {
		if (x == 0 || x == 1) {
			return x;
		}
		long r = x;
		long result = r * r;
		while (x < result) {
			r = (r + x / r) / 2;
			result = r * r;
		}
		return (int) r;
	}
}

