class Solution {
	int minCostClimbingStairs(int[] cost) {
		if (cost.length == 1) {
			return cost[0];
		}
		if (cost.length == 2) {
			return Math.min(cost[0],cost[1]);
		}
		int[] dp = new int[cost.length];
		dp[0] = cost[0];
		dp[1] = cost[1];
		for (int i = 2; i < cost.length; i++) {
			dp[i] = Math.min(dp[i - 1],dp[i - 2]) + cost[i];
		}
		return Math.min(dp[dp.length - 2],dp[dp.length - 1]);
	}
}

class Solution {
	int dp(int[] cost, int n, int[] book) {
		if (n == 0 || n == 1) {
			return 0;
		}
		if (book[n - 1] == -1) {
			book[n - 1] = Math.min(dp(cost,n - 1,book) + cost[n - 1],dp(cost,n - 2,book) + cost[n - 2]);
		}
		return book[n - 1];
	}
	int minCostClimbingStairs(int[] cost) {
		int n = cost.length;
		int[] book = new int[n];
		for (int i = 0; i < n; i++) {
			book[i] = -1;
		}
		return dp(cost,n,book);
	}
}

class Solution {
	int minCostClimbingStairs(int[] cost) {
		int len = cost.length;
		int[] mark = new int[len];
		return Math.min(minExpense(cost,0,len,mark),minExpense(cost,1,len,mark));
	}
	int minExpense(int[] cost, int cur, int len, int[] mark) {
		if (cur >= len) {
			return 0;
		}
		if (mark[cur] != 0) {
			return mark[cur];
		}
		int firstExpense = cost[cur] + minExpense(cost,cur + 1,len,mark);
		int secondExpense = cost[cur] + minExpense(cost,cur + 2,len,mark);
		mark[cur] = Math.min(firstExpense,secondExpense);
		return mark[cur];
	}
}

class Solution {
	int minCostClimbingStairs(int[] cost) {
		if (cost.length == 1) {
			return cost[0];
		}
		if (cost.length == 2) {
			return Math.max(cost[0],cost[1]);
		}
		if (cost.length == 3) {
			return Math.min(cost[0] + cost[2],cost[1]);
		}
		int[] dp = new int[cost.length + 1];
		dp[0] = 0;
		dp[1] = cost[0];
		dp[2] = Math.min(cost[0],cost[1]);
		dp[3] = Math.min(cost[0] + cost[2],cost[1]);
		for (int i = 4; i < dp.length; i++) {
			dp[i] = Math.min(dp[i - 2] + cost[i - 2],dp[i - 1] + cost[i - 1]);
		}
		return dp[dp.length - 1];
	}
}

