class Solution {
	String ret;
	String PrintMinNumber(int[] numbers) {
		dfs(numbers,0);
		return ret;
	}
	void dfs(int[] nums, int pos) {
		if (pos >= nums.length - 1) {
			StringBuilder sb = new StringBuilder();
			for (int i: nums) {	
				sb.append(i);
			}
			if (ret == null) {
				ret = sb.toString();
			} 
			else if (ret.compareTo(sb.toString()) > 0) {
				ret = sb.toString();
			}
		}
		for (int i = pos; i < nums.length; i++) {
			swap(nums,i,pos);
			dfs(nums,pos + 1);
			swap(nums,i,pos);
		}
	}
	void swap(int[] nums, int i, int j) {
		int tmp = nums[i];
		nums[i] = nums[j];
		nums[j] = tmp;
	}
}

class Solution {
	String PrintMinNumber(int[] numbers) {
		if (numbers.length == 0) {
			return "";
		}
		ArrayList<Integer> list = new ArrayList<>();
		for (int i = 0; i < numbers.length; i++) {
			list.add(numbers[i]);
		}
		Cmp c = new Cmp();
		list.sort(c);
		StringBuilder sb = new StringBuilder("");
		for (int i = 0; i < list.size(); i++) {
			sb.append(list.get(i));
		}
		return sb.toString();
	}
	class Cmp {
		int compare(Integer o1, Integer o2) {
			String p = Integer.toString(o1);
			String q = Integer.toString(o2);
			String a = p;
			a += q;
			String b = q;
			b += p;
			int i = Integer.parseInt(a) > Integer.parseInt(b) ? 1 : -1;
			return i;
		}
	}
}

