		for (int i = 0, j = 0, k = i_length - 1, t = j_length - 1; i <= k && j <= t; i++, j++, k--, t--) {
			for (int m = j; m <= t; m++) {
				ans.add(matrix[i][m]);
			}
			for (int m = i + 1; m <= k; m++) {
				ans.add(matrix[m][t]);
			}
			if (i != k) {
				for (int m = t - 1; m >= j; m--) {
					ans.add(matrix[k][m]);
				}
			}
			if (j != t) {
				for (int m = k - 1; m > i; m--) {
					ans.add(matrix[m][j]);
				}
			}
		}
		return ans;
	}
}

class Solution {
	ArrayList<Integer> printMatrix(int[][] matrix) {
		ArrayList<Integer> rest = new ArrayList<>();
		if (matrix.length == 0) {
			return rest;
		}
		int up = 0;
		int left = 0;
		int down = matrix.length - 1;
		int right = matrix[0].length - 1;
		while (left <= right && up <= down) {
			for (int i = left; i <= right; i++) {
				rest.add(matrix[up][i]);
			}
			up++;
			if (up > down) {
				break;
			}
			for (int i = up; i <= down; i++) {
				rest.add(matrix[i][right]);
			}
			right--;
			if (left > right) {
				break;
			}
			for (int i = right; i >= left; i--) {
				rest.add(matrix[down][i]);
			}
			down--;
			if (up > down) {
				break;
			}
			for (int i = down; i >= up; i--) {
				rest.add(matrix[i][left]);
			}
			left++;
			if (left > right) {
				break;
			}
		}
		return rest;
	}
}

class Solution {
	ArrayList<Integer> printMatrix(int[][] matrix) {
		ArrayList<Integer> list = new ArrayList<>();
		if (matrix.length == 0) {
			return list;
		}
		int n = matrix.length;
		int m = matrix[0].length;
		int low = 0;
		int high = n - 1;
		int left = 0;
		int right = m - 1;
		while (true) {
			for (int i = left; i <= right; i++) {
				list.add(matrix[low][i]);
			}
			if (++low > high) {
				break;
			}
			for (int i = low; i <= high; i++) {
				list.add(matrix[i][right]);
			}
			if (--right < left) {
				break;
			}
			for (int i = right; i >= left; i--) {
				list.add(matrix[high][i]);
			}
			if (--high < low) {
				break;
			}
			for (int i = high; i >= low; i--) {
				list.add(matrix[i][left]);
			}
			if (++left > right) {
				break;
			}
		}
		return list;
	}
}

