class Solution {
	int jumpFloor(int target) {
		if (target == 0) {
			return 0;
		}
		if (target == 1) {
			return 1;
		}
		int times = 1;
		int max = target / 2;
		int num = 1;
		for (int i = target - 1; i > max; i--) {
			long now = i;
			for (int j = 1; j < num; j++) {
				now = now * (i - j);
			}
			for (int j = 0; j < num; j++) {
				now = now / (j + 1);
			}
			times += now;
			num++;
		}
		if (target % 2 == 0) {
			times++;
		}
		return times;
	}
}

