class Solution {
	ArrayList<Integer> GetLeastNumbers_Solution(int[] input, int k) {
		if (input == null || input.length == 0 || k <= 0 || input.length < k) {
			return new ArrayList<Integer>();
		}
		int start = 0;
		int end = input.length - 1;
		int index = parition(input,start,end);
		while (index != k - 1) {
			if (index > k - 1) {
				end = index - 1;
				index = parition(input,start,end);
			} 
			else {
				start = index + 1;
				index = parition(input,start,end);
			}
		}
		ArrayList<Integer> result = new ArrayList<>();
		for (int i = 0; i < k; i++) {
			result.add(input[i]);
		}
		return result;
	}
	int parition(int[] data, int left, int right) {
		int index = new Random().nextInt((right - left + 1));
		int value = data[index + left];
		data[left + index] = data[left];
		data[left] = value;
		int j = left;
		for (int i = left + 1; i <= right; i++) {
			if (data[i] < value) {
				data[j] = data[i];
				j++;
				data[i] = data[j];
			}
		}
		data[j] = value;
		return j;
	}
}

class Solution {
	boolean isNumber(char c) {
		return c >= '0' && c <= '9';
	}
	int priority(char c) {
		if (c == '+' || c == '-') {
			return 1;
		}
		if (c == '*' || c == '/') {
			return 2;
		}
		return 0;
	}
	int res(char c, int o1, int o2) {
		if (c == '+') {
			return o1 + o2;
		}
		if (c == '-') {
			return o1 - o2;
		}
		if (c == '/') {
			return o1 / o2;
		}
		if (c == '*') {
			return o1 * o2;
		}
		return 0;
	}
	int solve(String s) {
		LinkedList<Integer> numStack = new LinkedList<>();
		LinkedList<Character> opsStack = new LinkedList<>();
		int len = s.length();
		for (int i = 0; i < len; i++) {
			char ch = s.charAt(i);
			if (ch == ' ') {
				continue;
			}
			if (isNumber(ch)) {
				int num = 0;
				while (i < len && isNumber(s.charAt(i))) {
					num = num * 10 + s.charAt(i) - '0';
					i++;
				}
				numStack.push(num);
				i--;
			} 
			else if (ch == '(') {
				opsStack.push(ch);
			} 
			else if (ch == ')') {
				while (!opsStack.isEmpty() && opsStack.peek() != '(') {
					Character op = opsStack.pop();
					Integer a = numStack.pop();
					Integer b = numStack.pop();
					int r = res(op,b,a);
					numStack.push(r);
				}
				opsStack.pop();
			} 
			else {
				while (!opsStack.isEmpty() && priority(ch) <= priority(opsStack.peek())) {
					Character op = opsStack.pop();
					Integer a = numStack.pop();
					Integer b = numStack.pop();
					int r = res(op,b,a);
					numStack.push(r);
				}
				opsStack.push(ch);
			}
		}
		while (!opsStack.isEmpty()) {
			Character op = opsStack.pop();
			Integer a = numStack.pop();
			Integer b = numStack.pop();
			int r = res(op,b,a);
			numStack.push(r);
		}
		return numStack.pop();
	}
}

