class Solution {
	boolean hasCycle(ListNode head) {
		ListNode p0 = head;
		ListNode p1 = head;
		if (head == null || head.next == null) {
			return false;
		} 
		else {
			p0 = head.next;
			p1 = head.next.next;
		}
		while (p1 != null && p1 != p0) {
			p0 = p0.next;
			p1 = p1.next;
			if (p1 != null) {
				p1 = p1.next;
			}
		}
		if (p1 == null) {
			return false;
		} 
		else {
			return true;
		}
	}
}

