		if (numbers == null || numbers.length == 0) {
			return -1;
		}
		int[] numbers2 = new int[numbers.length];
		for (int i = 0; i < numbers.length; i++) {
			numbers2[numbers[i]]++;
			if (numbers2[numbers[i]] % 2 == 0) {
				return numbers[i];
			}
		}
		return -1;
	}
}

