class Solution {
	int duplicate(int[] numbers) {
		for (int i = 0; i < numbers.length; i++) {
			while (i != numbers[i]) {
				if (numbers[i] == numbers[numbers[i]]) {
					return numbers[i];
				}
				swap(numbers,i,numbers[i]);
			}
		}
		return -1;
	}
	void swap(int[] numbers, int i, int j) {
		int tmp = numbers[i];
		numbers[i] = numbers[j];
		numbers[j] = tmp;
	}
}

