class Solution {
	int duplicate(int[] numbers) {
		int result = -1;
		if (numbers == null) {
			return result;
		}
		for (int i = 0, len = numbers.length; i < len; i++) {
			while (i != numbers[i]) {
				if (numbers[numbers[i]] == numbers[i]) {
					return numbers[i];
				}
				swap(i,numbers[i],numbers);
			}
			swap(i,numbers[i],numbers);
		}
		return result;
	}
	void swap(int x, int y, int[] num) {
		int temp = num[x];
		num[x] = num[y];
		num[y] = temp;
	}
}

class Solution {
	int duplicate(int[] numbers) {
		int length = numbers.length;
		int[] tempNumbers = new int[length];
		for (int i = 0; i < length; i++) {
			tempNumbers[i] = -1;
		}
		for (int num: numbers) {	
			if (num >= 0 && num <= length) {
				if (tempNumbers[num] != -1) {
					return num;
				} 
				else {
					tempNumbers[num] = num;
				}
			} 
			else {
				return -1;
			}
		}
		return -1;
	}
}

