class Solution {
	int duplicate(int[] numbers) {
		int num = -1;
		Map<Integer, Integer> hashmap = new HashMap<>();
		for (int i: numbers) {	
			int repeat = hashmap.getOrDefault(i,0);
			if (repeat != 0) {
				return i;
			} 
			else {
				hashmap.put(i,repeat + 1);
			}
		}
		return num;
	}
}

