class Solution {
	int duplicate(int[] numbers) {
		for (int i = 0; i < numbers.length; i++) {
			while (numbers[i] != i) {
				int k = numbers[i];
				if (numbers[k] == k) {
					return k;
				} 
				else {
					swap(numbers,i,k);
				}
			}
		}
		return -1;
	}
	void swap(int[] nums, int a, int b) {
		int tmp = nums[a];
		nums[a] = nums[b];
		nums[b] = tmp;
	}
}

class Solution {
