		int size = numbers.length;
		boolean[] results = new boolean[size];
		for (int i = 0; i < size; i++) {
			int num = numbers[i];
			if (num > 10000) {
				return -1;
			}
			if (results[num]) {
				return num;
			} 
			else {
				results[num] = true;
			}
		}
		return -1;
	}
}
